"use client";

import { useRef, useState, type ReactElement } from "react";

import { IconClose } from "@rhs-ui/icons";
import type { FolderNode, MoveToLabels } from "@rhs-ui/application/move-to-dialog/folders";
import { MoveToPanel } from "@rhs-ui/application/move-to-dialog/panel";
import { Dialog, DialogClose, DialogContent, DialogTrigger } from "@rhs-ui/primitives/dialog";
import { cn } from "@/lib/utils";

export type { FolderNode, MoveToLabels } from "@rhs-ui/application/move-to-dialog/folders";
export { MoveToPanel, type MoveToPanelProps } from "@rhs-ui/application/move-to-dialog/panel";
export { FolderTree, type FolderCreation, type FolderTreeProps } from "@rhs-ui/application/move-to-dialog/tree";

export interface MoveToDialogProps {
  /** The tree of folders, as nested nodes: `{ id, name, children, disabled, reason }`. Folders made in the dialog are added to it until your own list holds them too. */
  folders: readonly FolderNode[];
  /** The folder the items are in now. While moving it is marked "Already here" and cannot be chosen; while copying it is only marked. Its branch starts open. */
  currentFolderId?: string;
  /** The ids of folders that are themselves among the items. They, and everything inside them, cannot be the destination, and each says why. */
  movingIds?: readonly string[];
  /** How many items are on their way: it is in the title and in the sentence at the foot. Default 1. */
  itemCount?: number;
  /** Moving or copying. Default "move". */
  mode?: "move" | "copy";
  /** Does it, with the id of the chosen folder, for both modes. Return a promise: the dialog locks while it runs and closes when it resolves; when it rejects the dialog stays open with the message above the tree. */
  onMove: (folderId: string) => void | Promise<void>;
  /** Adds "New folder" and makes the folder, inside `parentId` (null for the top level) and named `name`. Resolve with the new folder's id, or the folder itself, so it can be chosen; reject to show why it failed. */
  onCreateFolder?: (parentId: string | null, name: string) => string | FolderNode | undefined | void | Promise<string | FolderNode | undefined | void>;
  /** The element that opens the dialog, usually a Button. Focus returns to it when the dialog closes. */
  trigger?: ReactElement;
  /** Whether the dialog is open, when you control it. */
  open?: boolean;
  /** Whether it is open to begin with. */
  defaultOpen?: boolean;
  /** Called when it opens or closes. A close that is refused while the items are on their way is not reported. */
  onOpenChange?: (open: boolean) => void;
  /** The language of the numbers and of "1 item" against "3 items". Default "en-US". */
  locale?: string;
  /** The words the dialog says, for translation. */
  labels?: MoveToLabels;
  /** Classes for the dialog panel, for a different width. */
  className?: string;
}

/**
 * Pick the destination folder for one item or many. A searchable tree with a file manager's keyboard, where the search expands
 * the matching branches; the folder the items are in is marked "Already here", and folders that cannot take them (the items
 * themselves and what is inside them) are disabled with the reason. New folder adds a field under the selection without leaving
 * the dialog. The foot spells the destination out as a path ("Moving 3 items to Projects / 2026 / Halcyon") and the button
 * names the folder, and the folder that is chosen is always in view in the tree. On a narrow dialog the reason a folder cannot be
 * chosen takes a second line under its name. Moving or copying, the dialog locks while it works and says why when it fails.
 */
export function MoveToDialog({ folders, currentFolderId, movingIds, itemCount, mode, onMove, onCreateFolder, trigger, open, defaultOpen = false, onOpenChange, locale, labels, className }: MoveToDialogProps) {
  const [ownOpen, setOwnOpen] = useState(defaultOpen);
  const [busy, setBusy] = useState(false);
  const busyNow = useRef(false);
  const content = useRef<HTMLDivElement>(null);
  const isOpen = open ?? ownOpen;

  function change(next: boolean) {
    // Items that are on their way cannot be walked away from.
    if (!next && busyNow.current) return;
    if (open === undefined) setOwnOpen(next);
    onOpenChange?.(next);
  }

  return (
    <Dialog open={isOpen} onOpenChange={change}>
      {trigger ? <DialogTrigger asChild>{trigger}</DialogTrigger> : null}
      <DialogContent
        ref={content}
        data-slot="move-to-dialog"
        showCloseButton={false}
        // Focus starts in the tree, on the folder the arrow keys start from: the keyboard is at work at once, and a phone is not made to raise its keyboard for the search field.
        onOpenAutoFocus={(event) => {
          const row = content.current?.querySelector<HTMLElement>('[role="treeitem"][tabindex="0"]');
          if (!row) return;
          event.preventDefault();
          row.focus({ preventScroll: true });
        }}
        // A field that is in the middle of something (a new folder's name, a search with text) takes Escape for itself and gives that up first; the dialog closes on the next one.
        onEscapeKeyDown={(event) => {
          if (busyNow.current || document.activeElement?.closest("[data-escape-local]")) event.preventDefault();
        }}
        className={cn("flex max-h-[calc(100dvh-2rem)] flex-col gap-0 overflow-hidden p-0 sm:max-w-lg", className)}
      >
        <MoveToPanel
          folders={folders}
          currentFolderId={currentFolderId}
          movingIds={movingIds}
          itemCount={itemCount}
          mode={mode}
          onMove={onMove}
          onCreateFolder={onCreateFolder}
          locale={locale}
          labels={labels}
          onClose={() => change(false)}
          onBusyChange={(next) => {
            busyNow.current = next;
            setBusy(next);
          }}
        />
        <DialogClose asChild>
          <button
            type="button"
            disabled={busy}
            aria-label={labels?.closeIcon ?? "Close"}
            // Level with the title: the header starts 8px lower from sm up (sm:pt-6), and the button goes down with it.
            className="absolute top-4 right-4 inline-flex size-7 items-center justify-center rounded-md text-muted-foreground transition-colors duration-150 outline-none hover:bg-muted hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/40 disabled:pointer-events-none disabled:opacity-50 sm:top-[1.3125rem]"
          >
            <IconClose size={16} />
          </button>
        </DialogClose>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { Fragment, useEffect, useLayoutEffect, useRef, useState, type KeyboardEvent, type ReactNode } from "react";

import { IconAlertCircle, IconFolderOpen, IconFolderPlus, IconSpinner } from "@rhs-ui/icons";
import {
  DEFAULT_LABELS,
  fill,
  folderNotes,
  messageOf,
  nameProblem,
  pathTo,
  plural,
  siblingsOf,
  visibleRows,
  withCreated,
  type CreatedFolder,
  type FolderNode,
  type MoveToLabels,
} from "@rhs-ui/application/move-to-dialog/folders";
import { FolderTree, type FolderCreation } from "@rhs-ui/application/move-to-dialog/tree";
import { Alert, AlertDescription, AlertTitle } from "@rhs-ui/primitives/alert";
import { Button } from "@rhs-ui/primitives/button";
import { DialogClose, DialogDescription, DialogTitle } from "@rhs-ui/primitives/dialog";
import { SearchInput } from "@rhs-ui/primitives/search-input";
import { cn } from "@/lib/utils";

export interface MoveToPanelProps {
  /** The tree of folders, as nested nodes: `{ id, name, children, disabled, reason }`. Folders you make in the panel are added to it until your own list holds them too. */
  folders: readonly FolderNode[];
  /** The folder the items are in now. While moving it is marked "Already here" and cannot be chosen; while copying it is only marked. Its branch starts open. */
  currentFolderId?: string;
  /** The ids of folders that are themselves among the items. They, and everything inside them, cannot be the destination, and each says why. */
  movingIds?: readonly string[];
  /** How many items are on their way: it is in the title and in the sentence at the foot. Default 1. */
  itemCount?: number;
  /** Moving or copying. Default "move". */
  mode?: "move" | "copy";
  /**
   * Does it, with the id of the chosen folder. Return a promise and the panel waits: the buttons and the tree lock while it runs, and
   * when it resolves `onClose` is called. When it rejects the panel stays as it is with the message above the tree.
   */
  onMove: (folderId: string) => void | Promise<void>;
  /** Adds "New folder" and makes the folder, inside `parentId` (null for the top level) and named `name`. Resolve with the new folder's id, or the folder itself, so it can be chosen; reject to show why it failed. */
  onCreateFolder?: (parentId: string | null, name: string) => string | FolderNode | undefined | void | Promise<string | FolderNode | undefined | void>;
  /** The chosen folder, when you control it. */
  value?: string | null;
  /** The folder chosen to begin with. Its branch starts open. */
  defaultValue?: string | null;
  /** Called with the id of the folder each time one is chosen. */
  onValueChange?: (id: string) => void;
  /** The search text to begin with. */
  defaultQuery?: string;
  /** Draw the panel on its own (a page, a sheet, a preview) instead of inside a Dialog. The title is then a plain heading. */
  standalone?: boolean;
  /** Called when the move is done, and when "Cancel" is pressed in a standalone panel. Inside a Dialog the button closes it. */
  onClose?: () => void;
  /** Called with true while the items are on their way and false after, so a dialog around the panel can refuse to close in the meantime. */
  onBusyChange?: (busy: boolean) => void;
  /** The language of the numbers and of "1 item" against "3 items". Default "en-US". */
  locale?: string;
  /** The words the panel says, for translation. */
  labels?: MoveToLabels;
  /** Classes for the panel. */
  className?: string;
}

function Heading({ standalone, className, children }: { standalone: boolean; className: string; children: ReactNode }) {
  return standalone ? <h2 className={className}>{children}</h2> : <DialogTitle className={className}>{children}</DialogTitle>;
}

function Lede({ standalone, className, children }: { standalone: boolean; className: string; children: ReactNode }) {
  return standalone ? <p className={className}>{children}</p> : <DialogDescription className={className}>{children}</DialogDescription>;
}

/** The sentence at the foot with the destination in it, spelled out as a path: Projects / 2026 / Halcyon. */
function Destination({ template, path }: { template: string; path: readonly FolderNode[] }) {
  const [before = "", ...after] = template.split("{path}");
  return (
    <>
      {before}
      <span className="font-medium text-foreground">
        {path.map((node, index) => (
          <Fragment key={node.id}>
            {index > 0 ? (
              <>
                <span aria-hidden="true" className="px-1 font-normal text-muted-foreground">
                  /
                </span>
                <span className="sr-only">, </span>
              </>
            ) : null}
            {node.name}
          </Fragment>
        ))}
      </span>
      {after.join("{path}")}
    </>
  );
}

interface Creating {
  parentId: string | null;
  name: string;
  error: string | null;
  pending: boolean;
}

/**
 * The inside of the move dialog, on its own. A searchable tree with a file manager's keyboard, where the search expands the
 * matching branches; the folder the items are in is marked "Already here", and the folders that cannot take them (the items
 * themselves and what is inside them, or any folder you disable) say why. "New folder" opens a field under the selection
 * without leaving the panel. The foot spells the destination out as a path ("Moving 3 items to Projects / 2026 / Halcyon") and
 * the button names the folder. Use it inside a Dialog, or with `standalone` anywhere else.
 */
export function MoveToPanel({
  folders,
  currentFolderId,
  movingIds = [],
  itemCount = 1,
  mode = "move",
  onMove,
  onCreateFolder,
  value,
  defaultValue = null,
  onValueChange,
  defaultQuery = "",
  standalone = false,
  onClose,
  onBusyChange,
  locale = "en-US",
  labels,
  className,
}: MoveToPanelProps) {
  const words = { ...DEFAULT_LABELS, ...labels };
  const [own, setOwn] = useState<string | null>(defaultValue);
  const [query, setQuery] = useState(defaultQuery);
  const [created, setCreated] = useState<readonly CreatedFolder[]>([]);
  const [creating, setCreating] = useState<Creating | null>(null);
  const [status, setStatus] = useState<"idle" | "pending">("idle");
  const [error, setError] = useState<string | null>(null);
  const [said, setSaid] = useState("");
  const [refocus, setRefocus] = useState<string | null>(null);
  const tree = withCreated(folders, created, locale);
  const [expanded, setExpanded] = useState<ReadonlySet<string>>(() => {
    const open = new Set<string>();
    for (const id of [currentFolderId, defaultValue ?? value ?? undefined]) {
      if (id) for (const node of (pathTo(folders, id) ?? []).slice(0, -1)) open.add(node.id);
    }
    return open;
  });
  const list = useRef<HTMLUListElement>(null);
  const scroller = useRef<HTMLDivElement>(null);
  const newButton = useRef<HTMLButtonElement>(null);
  const confirmButton = useRef<HTMLButtonElement>(null);
  const busy = useRef(false);
  // The dialog around the panel is told it is busy while the items move and while a folder is being made, and free again when neither is going on.
  const working = useRef(0);
  const begin = () => {
    working.current += 1;
    onBusyChange?.(true);
  };
  const end = () => {
    working.current = Math.max(0, working.current - 1);
    if (working.current === 0) onBusyChange?.(false);
  };

  const selected = value === undefined ? own : value;
  const pending = status === "pending";
  const count = Math.max(1, Math.round(itemCount));
  const notes = folderNotes(tree, { currentId: currentFolderId, movingIds, mode, labels: words });
  const { rows, matches } = visibleRows(tree, expanded, query);
  const path = selected ? pathTo(tree, selected) : null;
  const searching = query.trim() !== "";
  const figure = new Intl.NumberFormat(locale).format(count);
  const pick = (move: string, copy: string) => (mode === "move" ? move : copy);

  // Words for screen readers: how many folders a search left, and the folder that was just made.
  useEffect(() => {
    if (!searching) return;
    setSaid(matches === 0 ? "" : fill(plural(matches, words.matchesOne, words.matchesMany, locale), { count: new Intl.NumberFormat(locale).format(matches) }));
  }, [searching, matches]);

  // The folder that is chosen (or, with nothing chosen, the one the items are in) is brought into view in the tree when the panel opens, when a
  // different one is chosen and when the search changes: a destination named in the foot and on the button must not be somewhere out of sight in the
  // list. The tree's own box is moved, and never the page around it (scrollIntoView would move that too).
  useLayoutEffect(() => {
    const box = scroller.current;
    const find = (id: string) => box?.querySelector<HTMLElement>(`[data-folder-id="${CSS.escape(id)}"]`);
    const row = selected ? find(selected) : currentFolderId ? find(currentFolderId) : null;
    if (!box || !row) return;
    const top = row.offsetTop;
    const bottom = top + row.offsetHeight;
    if (top < box.scrollTop + 4) box.scrollTop = Math.max(0, top - 4);
    else if (bottom > box.scrollTop + box.clientHeight - 4) box.scrollTop = bottom - box.clientHeight + 4;
  }, [selected, query]); // eslint-disable-line react-hooks/exhaustive-deps

  // Focus goes where it was asked to once the row it names is on screen.
  useEffect(() => {
    if (refocus === null) return;
    list.current?.querySelector<HTMLElement>(`[data-folder-id="${CSS.escape(refocus)}"]`)?.focus({ preventScroll: true });
    setRefocus(null);
  }, [refocus]);

  function select(id: string) {
    if (value === undefined) setOwn(id);
    onValueChange?.(id);
    // The folder stays in view when the search is cleared.
    const above = (pathTo(tree, id) ?? []).slice(0, -1).map((node) => node.id);
    if (above.length) setExpanded((open) => new Set([...open, ...above]));
  }

  function toggle(id: string, open: boolean) {
    setExpanded((current) => {
      const next = new Set(current);
      if (open) next.add(id);
      else next.delete(id);
      return next;
    });
  }

  function startCreating() {
    if (creating) return;
    const parentId = selected && pathTo(tree, selected) ? selected : null;
    // The field is drawn under the folder it goes in, so the folder opens and the search steps aside.
    setQuery("");
    if (parentId) toggle(parentId, true);
    setCreating({ parentId, name: "", error: null, pending: false });
  }

  function stopCreating() {
    const parentId = creating?.parentId ?? null;
    setCreating(null);
    if (parentId) setRefocus(parentId);
    else newButton.current?.focus({ preventScroll: true });
  }

  async function createFolder() {
    if (!creating || creating.pending || !onCreateFolder) return;
    const problem = nameProblem(creating.name, siblingsOf(tree, creating.parentId), words);
    if (problem) {
      setCreating({ ...creating, error: problem });
      return;
    }
    const { parentId } = creating;
    const name = creating.name.trim();
    setCreating({ ...creating, pending: true, error: null });
    begin();
    try {
      const result = (await onCreateFolder(parentId, name)) as string | FolderNode | undefined;
      const node = typeof result === "string" ? { id: result, name } : result && typeof result === "object" ? result : null;
      if (node) {
        setCreated((current) => [...current, { parentId, node }]);
        select(node.id);
        setSaid(fill(words.created, { folder: node.name }));
        setRefocus(node.id);
      } else if (parentId) {
        setRefocus(parentId);
      } else {
        // The field is about to leave and nothing was chosen in its place: focus goes to the button that opened it, not to the page.
        newButton.current?.focus({ preventScroll: true });
      }
      setCreating(null);
    } catch (thrown) {
      setCreating((current) => (current ? { ...current, pending: false, error: messageOf(thrown) ?? words.createFailed } : current));
    } finally {
      end();
    }
  }

  async function confirm() {
    if (!selected || busy.current || creating?.pending) return;
    busy.current = true;
    setError(null);
    setStatus("pending");
    begin();
    // The tree and the buttons lock; the confirm button keeps focus, so a keyboard is not left on nothing while it works.
    confirmButton.current?.focus({ preventScroll: true });
    let done = false;
    try {
      await onMove(selected);
      done = true;
    } catch (thrown) {
      setError(messageOf(thrown) ?? words.failedBody);
    } finally {
      busy.current = false;
      setStatus("idle");
      end();
    }
    // After the busy flag is down: a dialog around the panel refuses to close while it is up.
    if (done) onClose?.();
  }

  function searchKeys(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key === "ArrowDown") {
      event.preventDefault();
      list.current?.querySelector<HTMLElement>('[role="treeitem"][tabindex="0"]')?.focus();
    } else if (event.key === "Enter") {
      // Type, press Enter: the first folder that matches and can be chosen is chosen.
      event.preventDefault();
      const first = rows.find((row) => (!searching || row.matched) && !notes.get(row.node.id)?.blocked);
      if (first) {
        select(first.node.id);
        setRefocus(first.node.id);
      }
    }
  }

  const creation: FolderCreation | null = creating
    ? {
        parentId: creating.parentId,
        level: (creating.parentId ? (pathTo(tree, creating.parentId)?.length ?? 0) : 0) + 1,
        value: creating.name,
        error: creating.error,
        pending: creating.pending,
        label: words.folderName,
        placeholder: words.folderPlaceholder,
        create: words.create,
        cancel: words.cancelCreate,
        onChange: (name) => setCreating((current) => (current ? { ...current, name, error: null } : current)),
        onSubmit: () => void createFolder(),
        onCancel: stopCreating,
      }
    : null;

  const template = path ? fill(plural(count, pick(words.summaryMoveOne, words.summaryCopyOne), pick(words.summaryMoveMany, words.summaryCopyMany), locale), { count: figure }) : null;
  const target = path?.[path.length - 1];
  const title = fill(plural(count, pick(words.titleMoveOne, words.titleCopyOne), pick(words.titleMoveMany, words.titleCopyMany), locale), { count: figure });

  return (
    <div data-slot="move-to-panel" data-status={status} className={cn("@container flex min-h-0 flex-col", className)}>
      <div className="shrink-0 px-5 pt-5 pr-14 pb-4 sm:px-6 sm:pt-6">
        <Heading standalone={standalone} className="text-lg leading-tight font-semibold tracking-[-0.02em]">
          {title}
        </Heading>
        <Lede standalone={standalone} className="mt-1.5 text-sm leading-relaxed text-muted-foreground">
          {words.description}
        </Lede>
      </div>

      <div className="relative grid min-h-0 flex-1 grid-cols-[minmax(0,1fr)] content-start gap-3 overflow-y-auto px-5 pb-5 sm:px-6">
        <div className="flex items-center gap-2">
          <SearchInput
            value={query}
            onValueChange={setQuery}
            aria-label={words.search}
            placeholder={words.search}
            disabled={pending}
            // While it holds text, the dialog leaves Escape to the field, which clears it.
            data-escape-local={query ? "" : undefined}
            onKeyDown={searchKeys}
            className="flex-1"
          />
          {onCreateFolder ? (
            // In a narrow panel the button is only its icon, and the words stay as its name.
            <Button ref={newButton} type="button" variant="outline" disabled={pending} onClick={startCreating} className="shrink-0 @max-sm:size-9 @max-sm:px-0">
              <IconFolderPlus />
              <span className="@max-sm:sr-only">{words.newFolder}</span>
            </Button>
          ) : null}
        </div>

        {error !== null ? (
          <Alert tone="destructive" role="alert" className="text-[color-mix(in_oklch,var(--destructive),var(--foreground)_20%)]">
            <IconAlertCircle />
            <AlertTitle>{pick(words.failedMove, words.failedCopy)}</AlertTitle>
            <AlertDescription>{error}</AlertDescription>
          </Alert>
        ) : null}

        {/* A little more than eight rows, so half of the ninth shows: a tree that ends exactly on a row does not say there is more below. */}
        <div ref={scroller} className="relative max-h-[18rem] min-h-36 overflow-y-auto rounded-lg border border-border bg-background p-1">
          {rows.length || creation ? (
            <FolderTree ref={list} rows={rows} notes={notes} selectedId={selected} query={query} label={words.tree} disabled={pending} creation={creation} onSelect={select} onOpenChange={toggle} />
          ) : (
            <p className="px-3 py-10 text-center text-sm text-muted-foreground [overflow-wrap:anywhere]">{searching ? fill(words.noMatch, { query: `“${query.trim()}”` }) : words.noFolders}</p>
          )}
        </div>

        {/* Where it is going, in words and as a path, with the room of two lines so the buttons below do not move as the path grows. */}
        <p aria-live="polite" className="flex min-h-9 items-start gap-2 text-[0.8125rem] leading-snug text-pretty text-muted-foreground">
          <IconFolderOpen aria-hidden="true" className="mt-px size-4 shrink-0" />
          <span className="min-w-0 break-words">{path && template ? <Destination template={template} path={path} /> : words.choose}</span>
        </p>
      </div>

      <div className="flex shrink-0 flex-col-reverse gap-2 border-t border-border bg-muted/30 px-5 py-4 sm:flex-row sm:justify-end sm:px-6">
        {standalone ? (
          <Button type="button" variant="outline" disabled={pending} onClick={onClose}>
            {words.cancel}
          </Button>
        ) : (
          <DialogClose asChild>
            <Button type="button" variant="outline" disabled={pending}>
              {words.cancel}
            </Button>
          </DialogClose>
        )}
        {/* Busy is said with aria-busy and aria-disabled, not disabled: a disabled button gives up focus, which would leave a keyboard on no control until the items are there. */}
        <Button
          ref={confirmButton}
          type="button"
          disabled={!selected && !pending}
          aria-busy={pending || undefined}
          aria-disabled={pending || creating?.pending || undefined}
          onClick={() => void confirm()}
          className="max-w-full min-w-0 aria-disabled:cursor-progress"
        >
          {pending ? <IconSpinner data-slot="button-spinner" /> : null}
          <span className="min-w-0 truncate">{target ? fill(pick(words.moveTo, words.copyTo), { folder: target.name }) : pick(words.moveBare, words.copyBare)}</span>
        </Button>
      </div>
      <p role="status" className="sr-only">
        {pending ? pick(words.moving, words.copying) : creating?.pending ? words.creating : said}
      </p>
    </div>
  );
}

"use client";

import { Fragment, useEffect, useId, useRef, useState, type ComponentProps, type KeyboardEvent } from "react";

import { IconCheck, IconChevronRight, IconClose, IconFolder, IconFolderOpen, IconSpinner } from "@rhs-ui/icons";
import { splitMatch, type FolderNote, type TreeRow } from "@rhs-ui/application/move-to-dialog/folders";
import { cn } from "@/lib/utils";

/** The row where a new folder is being named, drawn under the folder it goes in. */
export interface FolderCreation {
  /** The folder the new one goes in, or null for the top level. The row appears first among its folders. */
  parentId: string | null;
  /** How deep the row is, from 1. */
  level: number;
  /** What has been typed. */
  value: string;
  /** What is wrong with it, in words, or null. */
  error: string | null;
  /** The folder is being made: the field and the buttons are off. */
  pending: boolean;
  /** The name of the field, for screen readers. */
  label: string;
  /** The hint in the field. */
  placeholder: string;
  /** The name of the button that creates it. */
  create: string;
  /** The name of the button that gives up. */
  cancel: string;
  onChange: (value: string) => void;
  onSubmit: () => void;
  onCancel: () => void;
}

export interface FolderTreeProps extends Omit<ComponentProps<"ul">, "children" | "onSelect" | "role"> {
  /** The rows that are on screen, from `visibleRows`. */
  rows: readonly TreeRow[];
  /** A note for each folder that is not an ordinary destination: why it cannot be chosen, or a plain mark. */
  notes: ReadonlyMap<string, FolderNote>;
  /** The folder that is chosen. */
  selectedId: string | null;
  /** The search text, which is marked in the names. While there is some, the matching branches are open and the chevrons rest. */
  query: string;
  /** The name of the tree, for screen readers. */
  label: string;
  /** Nothing can be chosen or opened, because the items are on their way. */
  disabled?: boolean;
  /** The row where a new folder is being named. */
  creation?: FolderCreation | null;
  /** A folder that can be chosen was clicked or confirmed with the keyboard. */
  onSelect: (id: string) => void;
  /** A folder was opened or closed. */
  onOpenChange: (id: string, open: boolean) => void;
}

const INDENT = 16;
const INSET = 6;

/**
 * A folder tree for choosing one, with the keyboard of a file manager: Up and Down move, Right opens a folder or steps into it,
 * Left closes it or goes to its folder, Home and End jump, Enter and Space choose, and letters jump to the next name that starts
 * with them. Only one row is in the tab order. A folder that cannot be the destination stays reachable, so a screen reader
 * hears why, but it is not chosen.
 */
export function FolderTree({ rows, notes, selectedId, query, label, disabled = false, creation, onSelect, onOpenChange, className, ref, ...props }: FolderTreeProps) {
  const id = useId();
  const list = useRef<HTMLUListElement | null>(null);
  const [focused, setFocused] = useState<string | null>(null);
  const typed = useRef({ text: "", timer: 0 });
  const searching = query.trim() !== "";
  const ids = rows.map((row) => row.node.id);
  const active = focused && ids.includes(focused) ? focused : selectedId && ids.includes(selectedId) ? selectedId : (ids[0] ?? null);

  function attach(element: HTMLUListElement | null) {
    list.current = element;
    if (typeof ref === "function") ref(element);
    else if (ref) ref.current = element;
  }

  function moveTo(target: string) {
    setFocused(target);
    const find = () => list.current?.querySelector<HTMLElement>(`[data-folder-id="${CSS.escape(target)}"]`);
    const show = (row: HTMLElement | null | undefined) => {
      row?.focus();
      row?.scrollIntoView({ block: "nearest" });
    };
    // A row that is on screen is focused at once, so a key held down never outruns the focus; one that is about to be drawn gets it a frame later.
    const row = find();
    if (row) show(row);
    else window.requestAnimationFrame(() => show(find()));
  }

  function choose(row: TreeRow) {
    if (disabled || notes.get(row.node.id)?.blocked) return;
    onSelect(row.node.id);
  }

  function keys(event: KeyboardEvent<HTMLLIElement>, row: TreeRow) {
    if (event.target !== event.currentTarget || disabled) return;
    const index = rows.findIndex((entry) => entry.node.id === row.node.id);
    const go = (target?: TreeRow) => {
      if (!target) return;
      event.preventDefault();
      moveTo(target.node.id);
    };
    switch (event.key) {
      case "ArrowDown":
        return go(rows[index + 1]);
      case "ArrowUp":
        return go(rows[index - 1]);
      case "Home":
        return go(rows[0]);
      case "End":
        return go(rows[rows.length - 1]);
      case "ArrowRight":
        event.preventDefault();
        if (row.hasChildren && !row.open) onOpenChange(row.node.id, true);
        else if (row.hasChildren) go(rows[index + 1]);
        return;
      case "ArrowLeft":
        event.preventDefault();
        if (row.hasChildren && row.open && !searching) onOpenChange(row.node.id, false);
        else if (row.parent) moveTo(row.parent);
        return;
      case "Enter":
      case " ":
        event.preventDefault();
        choose(row);
        return;
      default: {
        if (event.key.length !== 1 || !/\S/.test(event.key) || event.ctrlKey || event.metaKey || event.altKey) return;
        // Letters typed in quick succession make one word, so "pro" finds Projects and not the next name with a p.
        window.clearTimeout(typed.current.timer);
        typed.current.text += event.key.toLowerCase();
        typed.current.timer = window.setTimeout(() => {
          typed.current.text = "";
        }, 700);
        const word = typed.current.text;
        const from = word.length === 1 ? index + 1 : index;
        const order = [...rows.slice(from), ...rows.slice(0, from)];
        go(order.find((entry) => entry.node.name.toLowerCase().startsWith(word)));
      }
    }
  }

  useEffect(() => () => window.clearTimeout(typed.current.timer), []);

  const field = creation ? <CreationRow key="creation" creation={creation} /> : null;

  return (
    <ul ref={attach} role="tree" aria-label={label} aria-busy={disabled || undefined} data-slot="folder-tree" className={cn("grid grid-cols-[minmax(0,1fr)] gap-px text-sm", disabled && "opacity-70", className)} {...props}>
      {creation && creation.parentId === null ? field : null}
      {rows.map((row) => {
        const note = notes.get(row.node.id);
        const blocked = note?.blocked === true;
        const selected = selectedId === row.node.id;
        const parts = row.matched ? splitMatch(row.node.name, query) : null;
        return (
          <Fragment key={row.node.id}>
            <li
              role="treeitem"
              data-folder-id={row.node.id}
              aria-level={row.level}
              aria-posinset={row.position}
              aria-setsize={row.size}
              aria-expanded={row.hasChildren ? row.open : undefined}
              aria-selected={selected}
              aria-disabled={blocked || undefined}
              aria-describedby={note ? `${id}-${row.node.id}-note` : undefined}
              tabIndex={row.node.id === active ? 0 : -1}
              onFocus={(event) => {
                if (event.target === event.currentTarget) setFocused(row.node.id);
              }}
              onKeyDown={(event) => keys(event, row)}
              onClick={() => {
                setFocused(row.node.id);
                if (disabled) return;
                choose(row);
                // A folder that cannot be the destination still opens: what is inside it may be.
                if (row.hasChildren && !row.open) onOpenChange(row.node.id, true);
              }}
              style={{ paddingLeft: (row.level - 1) * INDENT + INSET }}
              className={cn(
                "flex min-h-8 cursor-default items-center gap-x-1.5 rounded-md py-1 pr-2 outline-none select-none",
                "transition-colors duration-150 focus-visible:ring-[3px] focus-visible:ring-ring/40 motion-reduce:transition-none",
                // Why a folder cannot be chosen is the point of its row: on a narrow panel the reason takes a second line under the name, whole.
                blocked ? "cursor-not-allowed text-muted-foreground @max-md:flex-wrap" : "hover:bg-muted",
                selected && "bg-muted font-medium",
              )}
            >
              <span
                aria-hidden="true"
                onClick={(event) => {
                  if (!row.hasChildren || searching || disabled) return;
                  event.stopPropagation();
                  setFocused(row.node.id);
                  onOpenChange(row.node.id, !row.open);
                }}
                className={cn("grid size-5 shrink-0 place-items-center rounded text-muted-foreground", row.hasChildren && !searching && !disabled && "hover:bg-foreground/10 hover:text-foreground", !row.hasChildren && "invisible")}
              >
                <IconChevronRight size={14} className={cn("transition-transform duration-150 motion-reduce:transition-none", row.open && "rotate-90")} />
              </span>
              <span aria-hidden="true" className={cn("grid shrink-0 place-items-center", blocked ? "text-muted-foreground/70" : "text-muted-foreground")}>
                {row.open ? <IconFolderOpen size={16} /> : <IconFolder size={16} />}
              </span>
              <span className="min-w-[5rem] flex-1 truncate" title={row.node.name}>
                {parts ? (
                  <>
                    {parts[0]}
                    <mark className="rounded-[3px] bg-foreground/15 px-px font-semibold text-foreground">{parts[1]}</mark>
                    {parts[2]}
                  </>
                ) : (
                  row.node.name
                )}
              </span>
              {note ? (
                <span
                  id={`${id}-${row.node.id}-note`}
                  title={note.text}
                  className={cn(
                    "max-w-[44%] min-w-0 shrink truncate text-xs font-normal",
                    // Narrow: the reason has the width of the row, indented to the name (chevron, icon and two gaps), and is never cut off.
                    note.blocked
                      ? "text-muted-foreground @max-md:max-w-none @max-md:basis-full @max-md:overflow-visible @max-md:pl-12 @max-md:leading-snug @max-md:whitespace-normal"
                      : "rounded-full border border-border px-2 py-px text-[0.6875rem] text-muted-foreground",
                  )}
                >
                  {note.text}
                </span>
              ) : null}
              {selected ? <IconCheck aria-hidden="true" size={14} className="shrink-0" /> : null}
            </li>
            {creation && creation.parentId === row.node.id ? field : null}
          </Fragment>
        );
      })}
    </ul>
  );
}

function CreationRow({ creation }: { creation: FolderCreation }) {
  const id = useId();
  const input = useRef<HTMLInputElement>(null);
  const { error, pending } = creation;

  useEffect(() => {
    input.current?.focus({ preventScroll: true });
    input.current?.scrollIntoView({ block: "nearest" });
  }, []);

  return (
    <li
      role="treeitem"
      aria-level={creation.level}
      aria-selected={false}
      aria-label={creation.label}
      // The dialog around this tree sees this mark on whatever in the row has focus (the field, or one of its buttons) and leaves Escape to
      // the row: it gives up the new folder, not the dialog and the folder that was chosen in it.
      data-escape-local=""
      onKeyDown={(event) => {
        if (event.key !== "Escape") return;
        event.preventDefault();
        if (!pending) creation.onCancel();
      }}
      className="grid gap-1 py-0.5 pr-1"
      style={{ paddingLeft: (creation.level - 1) * INDENT + INSET }}
    >
      <div className="flex items-center gap-1.5">
        <span aria-hidden="true" className="size-5 shrink-0" />
        <IconFolder aria-hidden="true" size={16} className="shrink-0 text-muted-foreground" />
        <input
          ref={input}
          type="text"
          value={creation.value}
          // readOnly and aria-disabled, not disabled, while the folder is made: a disabled field lets go of focus, which would drop it on the dialog and leave nowhere to press Escape.
          readOnly={pending}
          aria-disabled={pending || undefined}
          autoComplete="off"
          spellCheck={false}
          aria-label={creation.label}
          aria-invalid={error ? true : undefined}
          aria-describedby={error ? `${id}-error` : undefined}
          placeholder={creation.placeholder}
          onChange={(event) => creation.onChange(event.target.value)}
          onKeyDown={(event) => {
            if (event.key !== "Enter") return;
            event.preventDefault();
            if (!pending) creation.onSubmit();
          }}
          className="h-7 min-w-0 flex-1 rounded-md border border-input bg-background px-2 text-sm outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/40 aria-disabled:opacity-60 aria-invalid:border-destructive"
        />
        <button
          type="button"
          aria-label={creation.create}
          // aria-disabled and not disabled while it works: the button has focus when it is pressed, and a disabled one would let go of it.
          aria-disabled={pending || undefined}
          onClick={() => !pending && creation.onSubmit()}
          className="grid size-7 shrink-0 place-items-center rounded-md bg-primary text-primary-foreground outline-none hover:bg-primary/90 focus-visible:ring-[3px] focus-visible:ring-ring/40 aria-disabled:cursor-progress"
        >
          {pending ? <IconSpinner size={14} /> : <IconCheck size={14} />}
        </button>
        <button
          type="button"
          aria-label={creation.cancel}
          aria-disabled={pending || undefined}
          onClick={() => !pending && creation.onCancel()}
          className="grid size-7 shrink-0 place-items-center rounded-md text-muted-foreground outline-none hover:bg-muted hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/40 aria-disabled:cursor-not-allowed aria-disabled:opacity-50"
        >
          <IconClose size={14} />
        </button>
      </div>
      {error ? (
        <p id={`${id}-error`} role="alert" className="pl-[1.625rem] text-xs font-medium text-destructive">
          {error}
        </p>
      ) : null}
    </li>
  );
}

/**
 * The folder logic behind the move dialog, as plain functions with no state and no hook: which folders can be chosen and
 * why not, which rows are on screen for a search, and where a new folder goes. A Server Component can use them too.
 */

/** One folder in the tree. */
export interface FolderNode {
  /** A stable identity: `onMove` receives it. */
  id: string;
  /** The name on the row, and in the path at the foot. */
  name: string;
  /** The folders inside it. */
  children?: readonly FolderNode[];
  /** Cannot be chosen as the destination, for a reason that is not about the items themselves: no permission, a full folder. Give a `reason`. */
  disabled?: boolean;
  /** Why it cannot be chosen, said on the row: "You can only view this folder". */
  reason?: string;
}

/** The words the dialog says, for translation. Use `{count}`, `{path}`, `{folder}` and `{query}` where the defaults do. */
export interface MoveToLabels {
  /** The title for one item that moves. Default "Move 1 item". */
  titleMoveOne?: string;
  /** The title for several that move. Default "Move {count} items". */
  titleMoveMany?: string;
  /** The title for one item that is copied. Default "Copy 1 item". */
  titleCopyOne?: string;
  /** The title for several that are copied. Default "Copy {count} items". */
  titleCopyMany?: string;
  /** The line under the title. Default "Choose the folder they should go to." */
  description?: string;
  /** The name of the search field, and its hint. Default "Search folders". */
  search?: string;
  /** The name of the tree, for screen readers. Default "Folders". */
  tree?: string;
  /** The button that adds a folder under the selection. Default "New folder". */
  newFolder?: string;
  /** The tag on the folder the items are already in, while moving. Default "Already here". */
  alreadyHere?: string;
  /** The tag on the folder the items are in, while copying (a copy can go there). Default "Current folder". */
  currentFolder?: string;
  /** Why the folder that is being moved cannot be the destination. Default "Can't move into itself". */
  selfMove?: string;
  /** Why the folder that is being copied cannot be the destination. Default "Can't copy into itself". */
  selfCopy?: string;
  /** Why a folder inside the one being moved cannot be the destination. Default "Inside the folder being moved". */
  insideMove?: string;
  /** Why a folder inside the one being copied cannot be the destination. Default "Inside the folder being copied". */
  insideCopy?: string;
  /** The tag on a disabled folder that gives no reason. Default "Not available". */
